// lru_cache.go

package main

import (
	"context"
	"fmt"
	"sync"
	"time"
)

type Cache[K comparable, V any] struct {
	mu        sync.RWMutex
	cache     map[K]*entry[K, V]
	ll        *list[K, V]
	capacity  int
	ttl       time.Duration
	ctx       context.Context
	cancel    context.CancelFunc
	cleaner   *time.Ticker
}

type entry[K comparable, V any] struct {
	key      K
	value    V
	expires  time.Time
	prev     *entry[K, V]
	next     *entry[K, V]
}

type list[K comparable, V any] struct {
	head, tail *entry[K, V]
}

func NewCache[K comparable, V any](capacity int, ttl time.Duration) *Cache[K, V] {
	ctx, cancel := context.WithCancel(context.Background())
	cache := &Cache[K, V]{
		mu:       sync.RWMutex{},
		cache:    make(map[K]*entry[K, V], capacity),
		ll:       &list[K, V]{},
		capacity: capacity,
		ttl:      ttl,
		ctx:      ctx,
		cancel:   cancel,
	}
	cache.startCleaner()
	return cache
}

func (c *Cache[K, V]) startCleaner() {
	interval := c.ttl / 10 // Clean expired entries every 10% of TTL
	c.cleaner = time.NewTicker(interval)
	go func() {
		for {
			select {
			case <-c.ctx.Done():
				return
			case <-c.cleaner.C:
				c.cleanExpired()
			}
		}
	}()
}

func (c *Cache[K, V]) Get(key K) (V, bool) {
	c.mu.RLock()
	defer c.mu.RUnlock()

	if ent, found := c.cache[key]; found && !ent.expires.Before(time.Now()) {
		c.ll.moveToFront(ent)
		return ent.value, true
	}
	delete(c.cache, key)
	return *new(V), false
}

func (c *Cache[K, V]) Put(key K, value V) {
	c.mu.Lock()
	defer c.mu.Unlock()

	if ent, found := c.cache[key]; found {
		ent.value = value
		ent.expires = time.Now().Add(c.ttl)
		c.ll.moveToFront(ent)
		return
	}

	if len(c.cache) >= c.capacity {
		c.evictOldest()
	}

	newEnt := &entry[K, V]{key: key, value: value, expires: time.Now().Add(c.ttl)}
	c.cache[key] = newEnt
	c.ll.pushToFront(newEnt)
}

func (c *Cache[K, V]) Delete(key K) {
	c.mu.Lock()
	defer c.mu.Unlock()

	if ent, found := c.cache[key]; found {
		delete(c.cache, key)
		c.ll.remove(ent)
	}
}

func (c *Cache[K, V]) evictOldest() {
	if c.ll.tail == nil {
		return
	}
	delete(c.cache, c.ll.tail.key)
	c.ll.remove(c.ll.tail)
}

func (c *Cache[K, V]) cleanExpired() {
	now := time.Now()
	c.mu.Lock()
	defer c.mu.Unlock()

	for ent := c.ll.head; ent != nil; {
		if ent.expires.Before(now) {
			delete(c.cache, ent.key)
			next := ent.next
			c.ll.remove(ent)
			ent = next
		} else {
			break
		}
	}
}

func (l *list[K, V]) pushToFront(e *entry[K, V]) {
	if l.head == nil {
		l.head = e
		l.tail = e
	} else {
		e.prev = l.head
		l.head.next = e
		l.head = e
	}
}

func (l *list[K, V]) moveToFront(e *entry[K, V]) {
	if e == l.head {
		return
	}
	if e.prev != nil {
		e.prev.next = e.next
	}
	if e.next != nil {
		e.next.prev = e.prev
	}
	if e == l.tail {
		l.tail = e.prev
	}
	e.prev = l.head
	e.next = l.head.next
	l.head.next = e
	if e.next != nil {
		e.next.prev = e
	}
}

func (l *list[K, V]) remove(e *entry[K, V]) {
	if e.prev != nil {
		e.prev.next = e.next
	}
	if e.next != nil {
		e.next.prev = e.prev
	}
	if e == l.head {
		l.head = e.next
	}
	if e == l.tail {
		l.tail = e.prev
	}
}

func (c *Cache[K, V]) Close() {
	c.cancel()
	c.cleaner.Stop()
}
