// main.go

package main

import (
	"context"
	"fmt"
	"sync"
	"time"
)

func worker(id int, cache *Cache[string, int], wg *sync.WaitGroup) {
	defer wg.Done()

	for i := 0; i < 5; i++ {
		key := fmt.Sprintf("key%d", id)
		value := id * 10 + i
		cache.Put(key, value)
		fmt.Printf("Worker %d: Put %s -> %d\n", id, key, value)

		v, found := cache.Get(key)
		if found {
			fmt.Printf("Worker %d: Get %s -> %d\n", id, key, v)
		} else {
			fmt.Printf("Worker %d: Get %s failed\n", id, key)
		}

		time.Sleep(100 * time.Millisecond)
	}
}

func main() {
	cache := NewCache[string, int](5, 2*time.Second)
	defer cache.Close()

	var wg sync.WaitGroup
	for i := 1; i <= 3; i++ {
		wg.Add(1)
		go worker(i, cache, &wg)
	}

	wg.Wait()
}
```

This code defines a generic LRU cache with TTL expiration and demonstrates its usage in a concurrent environment. The `main` function runs three goroutines that perform `Get` and `Put` operations on the cache. The cache is configured to have a capacity of 5 entries and a TTL of 2 seconds for each entry. The background cleaner goroutine removes expired entries every 200 milliseconds (10% of the TTL).
